{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Would you like to dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "I'm taking a break right now.", "or": true },
        { "speaker": "partner", "text": "No worries." },
        { "speaker": "you", "text": "Maybe next song." }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're an amazing dancer." },
        { "speaker": "partner", "text": "Thanks, you're doing great too." },
        { "speaker": "you", "text": "I'm a complete beginner." },
        { "speaker": "partner", "text": "You've got great rhythm." },
        { "speaker": "you", "text": "I appreciate it." }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "partner", "text": "Do you come here often?" },
        { "speaker": "you", "text": "It's my first time here." },
        { "speaker": "you", "text": "I come here all the time.", "or": true },
        { "speaker": "partner", "text": "How do you like the live band?" },
        { "speaker": "you", "text": "The music is incredible." }
      ]
    }
  ]
}
